@Component({
  selector: 'app-configuracion',
  standalone: true,
  templateUrl: './configuracion.component.html',
  styleUrl: './configuracion.component.css'
})
export class ConfiguracionComponent {}
<div class="configuracion-container">
  <h1>Configuración</h1>
  <p>Configura tu cuenta</p>
</div>
